JOIN (VALUES
	('Ali Sabieh'),
	('Arta'),
	('Dikhil'),
	('Djibouti'),
	('Obock'),
	('Tadjourah')
) AS v(name) ON c.code = 'DJ'
ON CONFLICT (name, country_id) DO NOTHING;

